```javascript
// Tab Switcher
document.querySelectorAll('[data-tabs]').forEach(container => {
  const tabs = container.querySelectorAll('[data-tab]');
  const panels = container.querySelectorAll('[data-panel]');

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      tabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      const target = tab.dataset.tab;
      panels.forEach(p => {
        p.classList.toggle('active', p.dataset.panel === target);
      });
    });
  });
});

// Accordion
document.querySelectorAll('[data-accordion]').forEach(container => {
  container.querySelectorAll('[data-accordion-trigger]').forEach(trigger => {
    trigger.addEventListener('click', () => {
      const item = trigger.closest('[data-accordion-item]');
      const isOpen = item.classList.contains('open');

      // Close all in same group
      container.querySelectorAll('[data-accordion-item]').forEach(i => {
        i.classList.remove('open');
      });

      if (!isOpen) {
        item.classList.add('open');
      }
    });
  });
});

// Carousel
class Carousel {
  constructor(el) {
    this.el = el;
    this.track = el.querySelector('[data-carousel-track]');
    this.slides = [...el.querySelectorAll('[data-carousel-slide]')];
    this.prevBtn = el.querySelector('[data-carousel-prev]');
    this.nextBtn = el.querySelector('[data-carousel-next]');
    this.dots = [...el.querySelectorAll('[data-carousel-dot]')];
    this.index = 0;
    this.autoInterval = null;

    this.prevBtn?.addEventListener('click', () => this.prev());
    this.nextBtn?.addEventListener('click', () => this.next());
    this.dots.forEach((dot, i) => {
      dot.addEventListener('click', () => this.goTo(i));
    });

    this.update();
    this.startAuto();
  }

  // ... methods
}

// Initialize all carousels
document.querySelectorAll('[data-carousel]').forEach(el => new Carousel(el));
```

