}

/* ==========================================================================
   LearnForge — Shared Stylesheet
   Brand: #000000 (primary), #E6FF32 (lime accent), #7F2A23 (burgundy)
   ========================================================================== */

/* --- CSS Custom Properties --- */
:root {
  --color-black: #000000;
  --color-lime: #E6FF32;
  --color-lime-hover: #D4ED1A;
  --color-burgundy: #7F2A23;
  --color-burgundy-light: #A8433A;
  --color-white: #FFFFFF;
  --color-off-white: #FAFAFA;
  --color-gray-50: #F9FAFB;
  --color-gray-100: #F3F4F6;
  --color-gray-200: #E5E7EB;
  --color-gray-300: #D1D5DB;
  --color-gray-400: #9CA3AF;
  --color-gray-500: #6B7280;
  --color-gray-600: #4B5563;
  --color-gray-700: #374151;
  --color-gray-800: #1F2937;
  --color-gray-900: #111827;

  --color-blue-600: #2563EB;
  --color-blue-700: #1D4ED8;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-heading: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.06);
  --shadow-card: 0 1px 3px rgba(0,0,0,0.06), 0 4px 12px rgba(0,0,0,0.04);

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --max-width: 1240px;
  --nav-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  overflow-x: hidden;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); line-height: 1.15; color: var(--color-black); }

/* --- Container --- */
.container { width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.container--narrow { max-width: 960px; }
.container--wide { max-width: 1400px; }

/* --- Buttons --- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 28px; font-weight: 600; font-size: 15px; font-family: var(--font-heading);
  border-radius: var(--radius-full); transition: all 0.2s ease; white-space: nowrap;
  letter-spacing: -0.01em;
}
.btn--primary { background: var(--color-black); color: var(--color-white); }
.btn--primary:hover { background: var(--color-gray-800); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn--accent { background: var(--color-lime); color: var(--color-black); }
.btn--accent:hover { background: var(--color-lime-hover); transform: translateY(-1px); box-shadow: var(--shadow-lg); }
.btn--outline { background: transparent; color: var(--color-black); border: 2px solid var(--color-gray-300); }
.btn--outline:hover { border-color: var(--color-black); background: var(--color-gray-50); }
.btn--white { background: var(--color-white); color: var(--color-black); }
.btn--white:hover { background: var(--color-gray-100); transform: translateY(-1px); box-shadow: var(--shadow-md); }
.btn--lg { padding: 16px 36px; font-size: 16px; }
.btn--sm { padding: 8px 20px; font-size: 14px; }

/* --- Navigation --- */
.nav { position: fixed; top: 0; left: 0; right: 0; z-index: 1000; height: var(--nav-height); background: var(--color-white); border-bottom: 1px solid var(--color-gray-100); transition: box-shadow 0.3s ease; }
.nav--scrolled { box-shadow: var(--shadow-md); }
.nav__inner { display: flex; align-items: center; justify-content: space-between; height: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.nav__logo { display: flex; align-items: center; gap: 10px; font-family: var(--font-heading); font-size: 22px; font-weight: 700; color: var(--color-black); letter-spacing: -0.02em; }
.nav__logo-icon { width: 34px; height: 34px; background: var(--color-black); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; color: var(--color-lime); font-weight: 800; font-size: 18px; }
.nav__links { display: flex; align-items: center; gap: 6px; }
.nav__link { padding: 8px 16px; font-size: 14px; font-weight: 500; color: var(--color-gray-700); border-radius: var(--radius-full); transition: all 0.2s ease; }
.nav__link:hover, .nav__link--active { color: var(--color-black); background: var(--color-gray-100); }
.nav__cta { margin-left: 12px; }
.nav__toggle { display: none; flex-direction: column; gap: 5px; padding: 8px; }
.nav__toggle span { width: 22px; height: 2px; background: var(--color-black); border-radius: 2px; transition: all 0.3s ease; }
.nav__toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav__toggle.active span:nth-child(2) { opacity: 0; }
.nav__toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.nav__mobile { display: none; position: fixed; top: var(--nav-height); left: 0; right: 0; bottom: 0; background: var(--color-white); z-index: 999; padding: 24px; flex-direction: column; gap: 4px; overflow-y: auto; }
.nav__mobile.open { display: flex; }
.nav__mobile .nav__link { font-size: 16px; padding: 14px 20px; }
.nav__mobile .btn { margin-top: 16px; width: 100%; }

/* --- Section Base --- */
.section { padding: 100px 0; }
.section--tight { padding: 64px 0; }
.section--dark { background: var(--color-black); color: var(--color-white); }
.section--dark h2, .section--dark h3, .section--dark h4 { color: var(--color-white); }
.section--gray { background: var(--color-gray-50); }
.section--lime { background: var(--color-lime); }
.section__header { text-align: center; max-width: 720px; margin: 0 auto 60px; }
.section__label { display: inline-block; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--color-blue-600); margin-bottom: 16px; }
.section--dark .section__label { color: var(--color-lime); }
.section__title { font-size: clamp(32px, 5vw, 48px); font-weight: 800; letter-spacing: -0.02em; margin-bottom: 20px; }
.section__subtitle { font-size: 18px; color: var(--color-gray-500); line-height: 1.7; max-width: 600px; margin: 0 auto; }
.section--dark .section__subtitle { color: var(--color-gray-400); }

/* --- Hero Section --- */
.hero { padding: 160px 0 80px; text-align: center; background: var(--color-white); position: relative; overflow: hidden; }
.hero::before { content: ''; position: absolute; top: -200px; right: -200px; width: 600px; height: 600px; background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%); border-radius: 50%; pointer-events: none; }
.hero::after { content: ''; position: absolute; bottom: -100px; left: -100px; width: 400px; height: 400px; background: radial-gradient(circle, rgba(127,42,35,0.08) 0%, transparent 70%); border-radius: 50%; pointer-events: none; }
.hero__inner { position: relative; z-index: 1; max-width: 900px; margin: 0 auto; }
.hero__badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 16px; background: var(--color-lime); color: var(--color-black); border-radius: var(--radius-full); font-size: 13px; font-weight: 700; margin-bottom: 32px; }
.hero__badge-dot { width: 7px; height: 7px; background: var(--color-black); border-radius: 50%; animation: pulse 2s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.3; } }
.hero__title { font-size: clamp(36px, 7vw, 64px); font-weight: 800; letter-spacing: -0.03em; line-height: 1.1; margin-bottom: 24px; }
.hero__title-accent { color: var(--color-burgundy); }
.hero__subtitle { font-size: clamp(16px, 2.5vw, 19px); color: var(--color-gray-500); max-width: 640px; margin: 0 auto 40px; line-height: 1.65; }
.hero__actions { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; margin-bottom: 56px; }

/* Hero Tab Switch */
.hero__tabs { display: inline-flex; background: var(--color-gray-100); border-radius: var(--radius-full); padding: 4px; margin-bottom: 48px; }
.hero__tab { padding: 12px 28px; font-size: 14px; font-weight: 600; border-radius: var(--radius-full); transition: all 0.3s ease; color: var(--color-gray-500); font-family: var(--font-heading); }
.hero__tab.active { background: var(--color-black); color: var(--color-white); box-shadow: var(--shadow-md); }
.hero__preview { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); box-shadow: var(--shadow-xl); overflow: hidden; max-width: 900px; margin: 0 auto; }
.hero__preview-header { display: flex; align-items: center; gap: 8px; padding: 14px 20px; background: var(--color-gray-50); border-bottom: 1px solid var(--color-gray-200); }
.hero__preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.hero__preview-dot:nth-child(1) { background: #FF5F57; } .hero__preview-dot:nth-child(2) { background: #FFBD2E; } .hero__preview-dot:nth-child(3) { background: #28CA41; }
.hero__preview-body { display: flex; min-height: 320px; }
.hero__preview-sidebar { width: 200px; background: var(--color-gray-50); border-right: 1px solid var(--color-gray-200); padding: 20px; display: flex; flex-direction: column; gap: 4px; }
.hero__preview-main { flex: 1; padding: 28px; background: var(--color-white); }
.hero__preview-panel { display: none; }
.hero__preview-panel.active { display: block; }

.hero__preview-nav-item { padding: 10px 14px; font-size: 13px; font-weight: 500; border-radius: var(--radius-sm); color: var(--color-gray-600); transition: all 0.15s; }
.hero__preview-nav-item.active { background: var(--color-black); color: var(--color-white); }
.hero__preview-nav-item:not(.active):hover { background: var(--color-gray-200); }

.hero__preview-stat-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 24px; }
.hero__preview-stat { background: var(--color-gray-50); border-radius: var(--radius-md); padding: 16px; }
.hero__preview-stat-value { font-size: 22px; font-weight: 700; font-family: var(--font-heading); color: var(--color-black); }
.hero__preview-stat-label { font-size: 12px; color: var(--color-gray-500); margin-top: 2px; }
.hero__preview-chart { background: var(--color-gray-50); border-radius: var(--radius-md); height: 120px; display: flex; align-items: flex-end; gap: 8px; padding: 20px; }
.hero__preview-bar { flex: 1; background: var(--color-black); border-radius: 4px 4px 0 0; transition: height 0.3s; }
.hero__preview-bar:nth-child(1) { height: 60%; } .hero__preview-bar:nth-child(2) { height: 85%; }
.hero__preview-bar:nth-child(3) { height: 45%; } .hero__preview-bar:nth-child(4) { height: 75%; }
.hero__preview-bar:nth-child(5) { height: 55%; } .hero__preview-bar:nth-child(6) { height: 90%; }
.hero__preview-bar:nth-child(7) { height: 70%; } .hero__preview-bar:nth-child(8) { height: 50%; }

.hero__preview-student-course { display: flex; gap: 16px; flex-wrap: wrap; }
.hero__preview-course-card { flex: 1; min-width: 140px; border: 1px solid var(--color-gray-200); border-radius: var(--radius-md); overflow: hidden; }
.hero__preview-course-thumb { height: 80px; background: linear-gradient(135deg, var(--color-gray-200), var(--color-gray-300)); display: flex; align-items: center; justify-content: center; }
.hero__preview-course-thumb-icon { width: 32px; height: 32px; background: var(--color-black); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--color-lime); font-size: 14px; }
.hero__preview-course-info { padding: 12px; }
.hero__preview-course-title { font-size: 13px; font-weight: 600; font-family: var(--font-heading); }
.hero__preview-course-meta { font-size: 11px; color: var(--color-gray-400); margin-top: 2px; }
.hero__preview-progress { margin-top: 24px; }
.hero__preview-progress-bar { height: 8px; background: var(--color-gray-200); border-radius: var(--radius-full); overflow: hidden; margin-top: 8px; }
.hero__preview-progress-fill { height: 100%; background: var(--color-black); border-radius: var(--radius-full); width: 65%; }

/* --- Stats Bar --- */
.stats-bar { padding: 32px 0; border-top: 1px solid var(--color-gray-100); border-bottom: 1px solid var(--color-gray-100); background: var(--color-white); }
.stats-bar--dark { background: var(--color-black); border-color: var(--color-gray-800); }
.stats-bar--dark .stat-item__value { color: var(--color-lime); }
.stats-bar--dark .stat-item__label { color: var(--color-gray-400); }
.stats-bar__inner { display: flex; justify-content: center; gap: 80px; flex-wrap: wrap; }
.stat-item { text-align: center; }
.stat-item__value { font-size: clamp(28px, 5vw, 40px); font-weight: 800; font-family: var(--font-heading); color: var(--color-black); letter-spacing: -0.02em; }
.stat-item__label { font-size: 14px; color: var(--color-gray-500); margin-top: 4px; font-weight: 500; }

/* --- Product Cards Grid --- */
.product-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.product-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 36px 28px; transition: all 0.3s ease; position: relative; overflow: hidden; }
.product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-xl); border-color: transparent; }
.product-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 4px; }
.product-card:nth-child(1)::before { background: var(--color-black); }
.product-card:nth-child(2)::before { background: var(--color-burgundy); }
.product-card:nth-child(3)::before { background: var(--color-lime); }
.product-card:nth-child(4)::before { background: var(--color-blue-600); }
.product-card__icon { width: 52px; height: 52px; border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 24px; margin-bottom: 24px; }
.product-card:nth-child(1) .product-card__icon { background: rgba(0,0,0,0.05); }
.product-card:nth-child(2) .product-card__icon { background: rgba(127,42,35,0.08); }
.product-card:nth-child(3) .product-card__icon { background: rgba(230,255,50,0.3); }
.product-card:nth-child(4) .product-card__icon { background: rgba(37,99,235,0.08); }
.product-card__title { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
.product-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; margin-bottom: 24px; }
.product-card__link { font-size: 14px; font-weight: 600; color: var(--color-blue-600); transition: color 0.2s; display: inline-flex; align-items: center; gap: 6px; }
.product-card__link:hover { color: var(--color-blue-700); }
.product-card__link-arrow { transition: transform 0.2s; }
.product-card__link:hover .product-card__link-arrow { transform: translateX(4px); }

/* --- Why Choose Us Tabs --- */
.why-tabs { max-width: 900px; margin: 0 auto; }
.why-tabs__nav { display: flex; gap: 8px; margin-bottom: 40px; flex-wrap: wrap; justify-content: center; }
.why-tabs__trigger { padding: 12px 24px; font-size: 14px; font-weight: 600; border-radius: var(--radius-full); transition: all 0.3s ease; color: var(--color-gray-600); border: 1px solid var(--color-gray-200); background: var(--color-white); font-family: var(--font-heading); }
.why-tabs__trigger:hover { border-color: var(--color-gray-300); }
.why-tabs__trigger.active { background: var(--color-black); color: var(--color-white); border-color: var(--color-black); }
.why-tabs__panel { display: none; animation: fadeSlideIn 0.4s ease; }
.why-tabs__panel.active { display: block; }
@keyframes fadeSlideIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.why-tabs__panel-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.why-tabs__panel-visual { background: var(--color-gray-50); border-radius: var(--radius-lg); padding: 32px; min-height: 280px; display: flex; align-items: center; justify-content: center; }
.why-tabs__panel-visual-icon { width: 80px; height: 80px; background: var(--color-black); border-radius: var(--radius-lg); display: flex; align-items: center; justify-content: center; color: var(--color-lime); font-size: 36px; }
.why-tabs__panel-title { font-size: 24px; font-weight: 700; margin-bottom: 16px; }
.why-tabs__panel-desc { font-size: 15px; color: var(--color-gray-500); line-height: 1.7; margin-bottom: 20px; }
.why-tabs__panel-features { display: flex; flex-direction: column; gap: 12px; }
.why-tabs__panel-feature { display: flex; align-items: flex-start; gap: 12px; font-size: 14px; color: var(--color-gray-600); padding: 10px 14px; background: var(--color-gray-50); border-radius: var(--radius-md); }
.why-tabs__panel-check { flex-shrink: 0; width: 20px; height: 20px; background: var(--color-lime); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; color: var(--color-black); margin-top: 1px; }

/* --- Cards Grid (general) --- */
.cards-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.cards-grid--4 { grid-template-columns: repeat(4, 1fr); }
.info-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 32px; transition: all 0.3s ease; }
.info-card:hover { box-shadow: var(--shadow-lg); border-color: transparent; }
.info-card__icon { width: 48px; height: 48px; background: var(--color-gray-50); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 22px; margin-bottom: 20px; }
.info-card__title { font-size: 18px; font-weight: 700; margin-bottom: 10px; }
.info-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.65; }

/* --- Global Scale --- */
.global-scale { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.global-scale__map { background: var(--color-gray-50); border-radius: var(--radius-lg); padding: 40px; min-height: 300px; display: flex; align-items: center; justify-content: center; position: relative; }
.global-scale__map-dots { position: relative; width: 100%; height: 200px; }
.global-scale__dot { position: absolute; width: 8px; height: 8px; background: var(--color-black); border-radius: 50%; animation: dotPulse 2s infinite; }
.global-scale__dot:nth-child(1) { top: 20%; left: 15%; } .global-scale__dot:nth-child(2) { top: 25%; left: 45%; }
.global-scale__dot:nth-child(3) { top: 40%; left: 55%; } .global-scale__dot:nth-child(4) { top: 30%; left: 75%; }
.global-scale__dot:nth-child(5) { top: 60%; left: 25%; } .global-scale__dot:nth-child(6) { top: 50%; left: 65%; }
.global-scale__dot:nth-child(7) { top: 70%; left: 50%; } .global-scale__dot:nth-child(8) { top: 45%; left: 85%; }
@keyframes dotPulse { 0%, 100% { transform: scale(1); opacity: 0.6; } 50% { transform: scale(2); opacity: 1; } }
.global-scale__content h2 { font-size: 36px; font-weight: 800; margin-bottom: 20px; letter-spacing: -0.02em; }
.global-scale__content p { font-size: 16px; color: var(--color-gray-500); line-height: 1.7; margin-bottom: 28px; }
.global-scale__checks { display: flex; flex-direction: column; gap: 12px; }
.global-scale__check { display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 500; }
.global-scale__check-icon { width: 24px; height: 24px; background: var(--color-lime); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 13px; flex-shrink: 0; }

/* --- AI Automations --- */
.ai-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }
.ai-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 28px; text-align: center; transition: all 0.3s ease; }
.ai-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.ai-card__icon { width: 56px; height: 56px; background: linear-gradient(135deg, var(--color-black), var(--color-gray-800)); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 26px; margin: 0 auto 16px; color: var(--color-lime); }
.ai-card__title { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.ai-card__desc { font-size: 13px; color: var(--color-gray-500); line-height: 1.5; }

/* --- Testimonials Carousel --- */
.testimonials { position: relative; overflow: hidden; }
.testimonials__track { display: flex; transition: transform 0.5s ease; }
.testimonials__slide { flex: 0 0 100%; padding: 0 12px; }
.testimonials__grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.testimonial-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 32px; transition: all 0.3s ease; }
.testimonial-card:hover { box-shadow: var(--shadow-lg); }
.testimonial-card__stars { color: var(--color-lime); font-size: 16px; margin-bottom: 16px; letter-spacing: 2px; }
.testimonial-card__quote { font-size: 15px; color: var(--color-gray-600); line-height: 1.7; margin-bottom: 24px; font-style: italic; }
.testimonial-card__author { display: flex; align-items: center; gap: 12px; }
.testimonial-card__avatar { width: 44px; height: 44px; border-radius: 50%; background: var(--color-gray-200); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 16px; font-family: var(--font-heading); color: var(--color-gray-600); }
.testimonial-card__name { font-size: 14px; font-weight: 700; }
.testimonial-card__role { font-size: 12px; color: var(--color-gray-400); }
.testimonials__controls { display: flex; align-items: center; justify-content: center; gap: 16px; margin-top: 36px; }
.testimonials__btn { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--color-gray-300); display: flex; align-items: center; justify-content: center; transition: all 0.2s; font-size: 18px; background: var(--color-white); }
.testimonials__btn:hover { background: var(--color-black); color: var(--color-white); border-color: var(--color-black); }
.testimonials__dots { display: flex; gap: 8px; }
.testimonials__dot { width: 10px; height: 10px; border-radius: 50%; background: var(--color-gray-300); transition: all 0.3s; cursor: pointer; }
.testimonials__dot.active { background: var(--color-black); width: 28px; border-radius: var(--radius-full); }

/* --- Pricing --- */
.pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; max-width: 1000px; margin: 0 auto 40px; }
.pricing-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 36px; transition: all 0.3s ease; position: relative; }
.pricing-card:hover { box-shadow: var(--shadow-xl); }
.pricing-card--featured { border-color: var(--color-black); box-shadow: var(--shadow-lg); transform: scale(1.03); }
.pricing-card--featured:hover { transform: scale(1.03) translateY(-4px); }
.pricing-card__badge { display: inline-block; padding: 4px 12px; background: var(--color-lime); border-radius: var(--radius-full); font-size: 12px; font-weight: 700; margin-bottom: 20px; }
.pricing-card__name { font-size: 20px; font-weight: 700; margin-bottom: 8px; }
.pricing-card__price { font-size: 40px; font-weight: 800; font-family: var(--font-heading); letter-spacing: -0.02em; margin-bottom: 4px; }
.pricing-card__period { font-size: 14px; color: var(--color-gray-500); margin-bottom: 24px; }
.pricing-card__features { display: flex; flex-direction: column; gap: 14px; margin-bottom: 32px; }
.pricing-card__feature { display: flex; align-items: flex-start; gap: 10px; font-size: 14px; color: var(--color-gray-600); }
.pricing-card__feature-check { flex-shrink: 0; color: var(--color-lime); font-weight: 700; }
.pricing-card .btn { width: 100%; }
.pricing-enterprise { max-width: 700px; margin: 0 auto; text-align: center; padding: 32px; background: var(--color-gray-50); border-radius: var(--radius-lg); }
.pricing-enterprise__title { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
.pricing-enterprise__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; margin-bottom: 20px; }
.pricing-note { text-align: center; font-size: 13px; color: var(--color-gray-400); margin-top: 20px; }

/* --- Integrations --- */
.integrations-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 20px; max-width: 900px; margin: 0 auto; }
.integration-item { display: flex; align-items: center; justify-content: center; padding: 28px 20px; background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-md); transition: all 0.3s ease; }
.integration-item:hover { box-shadow: var(--shadow-md); border-color: transparent; transform: translateY(-2px); }
.integration-item__logo { font-size: 28px; font-weight: 800; font-family: var(--font-heading); color: var(--color-gray-700); }
.integration-item__logo--stripe { color: #635BFF; } .integration-item__logo--zapier { color: #FF4A00; }
.integration-item__logo--ga { color: #E37400; } .integration-item__logo--mailchimp { color: #FFE01B; }
.integration-item__logo--paypal { color: #003087; } .integration-item__logo--calendly { color: #006BFF; }

/* --- Social Proof --- */
.social-proof { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.social-proof__item { text-align: center; padding: 24px; }
.social-proof__icon { font-size: 36px; margin-bottom: 12px; }
.social-proof__value { font-size: 28px; font-weight: 800; font-family: var(--font-heading); color: var(--color-black); }
.social-proof__label { font-size: 14px; color: var(--color-gray-500); margin-top: 4px; }

/* --- FAQ Accordion --- */
.faq { max-width: 700px; margin: 0 auto; }
.faq__item { border-bottom: 1px solid var(--color-gray-200); }
.faq__trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 22px 0; font-size: 16px; font-weight: 600; text-align: left; color: var(--color-black); transition: color 0.2s; gap: 16px; font-family: var(--font-heading); }
.faq__trigger:hover { color: var(--color-gray-600); }
.faq__icon { flex-shrink: 0; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: var(--color-gray-100); transition: all 0.3s ease; font-size: 18px; font-weight: 300; }
.faq__item.open .faq__icon { background: var(--color-black); color: var(--color-white); transform: rotate(45deg); }
.faq__answer { max-height: 0; overflow: hidden; transition: max-height 0.4s ease, padding 0.4s ease; }
.faq__item.open .faq__answer { max-height: 300px; padding-bottom: 22px; }
.faq__answer p { font-size: 15px; color: var(--color-gray-500); line-height: 1.7; }

/* --- CTA Banner --- */
.cta-banner { background: var(--color-black); border-radius: var(--radius-xl); padding: 64px; text-align: center; color: var(--color-white); }
.cta-banner__title { font-size: 36px; font-weight: 800; color: var(--color-white); margin-bottom: 16px; letter-spacing: -0.02em; }
.cta-banner__desc { font-size: 17px; color: var(--color-gray-400); max-width: 500px; margin: 0 auto 32px; line-height: 1.6; }
.cta-banner__actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* --- Course Builder Features --- */
.feature-alt { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; margin: 48px 0; }
.feature-alt:nth-child(even) { direction: rtl; }
.feature-alt:nth-child(even) .feature-alt__content { direction: ltr; }
.feature-alt__visual { background: var(--color-gray-50); border-radius: var(--radius-lg); min-height: 280px; display: flex; align-items: center; justify-content: center; }
.feature-alt__visual-icon { font-size: 64px; }
.feature-alt__title { font-size: 28px; font-weight: 700; margin-bottom: 14px; }
.feature-alt__desc { font-size: 15px; color: var(--color-gray-500); line-height: 1.7; margin-bottom: 20px; }
.feature-alt__list { display: flex; flex-direction: column; gap: 10px; }
.feature-alt__item { display: flex; align-items: center; gap: 10px; font-size: 14px; color: var(--color-gray-600); }

/* --- Product Demo Accordion --- */
.product-demo { border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); overflow: hidden; }
.product-demo__trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 24px 32px; font-size: 18px; font-weight: 700; background: var(--color-white); transition: background 0.2s; font-family: var(--font-heading); }
.product-demo__trigger:hover { background: var(--color-gray-50); }
.product-demo__arrow { transition: transform 0.3s; font-size: 20px; }
.product-demo.open .product-demo__arrow { transform: rotate(180deg); }
.product-demo__content { max-height: 0; overflow: hidden; transition: max-height 0.5s ease; }
.product-demo.open .product-demo__content { max-height: 600px; }
.product-demo__inner { padding: 0 32px 32px; }
.product-demo__demo { background: var(--color-gray-50); border-radius: var(--radius-md); padding: 40px; display: flex; gap: 24px; flex-wrap: wrap; }
.product-demo__demo-block { flex: 1; min-width: 200px; }
.product-demo__demo-block-title { font-size: 14px; font-weight: 700; margin-bottom: 12px; }
.product-demo__demo-item { background: var(--color-white); border-radius: var(--radius-sm); padding: 10px 14px; margin-bottom: 6px; font-size: 13px; border: 1px solid var(--color-gray-200); display: flex; align-items: center; gap: 8px; }
.product-demo__demo-item-icon { color: var(--color-lime); }

/* --- Tools Grid --- */
.tools-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
.tool-item { text-align: center; padding: 24px 16px; background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-md); transition: all 0.3s ease; }
.tool-item:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.tool-item__icon { font-size: 28px; margin-bottom: 10px; }
.tool-item__name { font-size: 13px; font-weight: 600; }

/* --- File Types Grid --- */
.file-types { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }
.file-type { display: flex; align-items: center; gap: 12px; padding: 20px; background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-md); transition: all 0.3s; }
.file-type:hover { box-shadow: var(--shadow-md); }
.file-type__icon { width: 42px; height: 42px; background: var(--color-gray-50); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 20px; }
.file-type__name { font-size: 14px; font-weight: 600; }

/* --- Three Steps --- */
.steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.step { text-align: center; position: relative; }
.step__number { width: 56px; height: 56px; background: var(--color-black); color: var(--color-lime); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 22px; font-weight: 800; margin: 0 auto 24px; font-family: var(--font-heading); }
.step__title { font-size: 20px; font-weight: 700; margin-bottom: 10px; }
.step__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; }
.step__connector { display: none; }

/* --- Coaching Spotlight --- */
.spotlight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.spotlight-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); overflow: hidden; transition: all 0.3s; }
.spotlight-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.spotlight-card__header { padding: 48px 28px; text-align: center; background: var(--color-gray-50); }
.spotlight-card__icon { width: 64px; height: 64px; background: var(--color-black); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 24px; color: var(--color-lime); margin: 0 auto 16px; }
.spotlight-card__name { font-size: 18px; font-weight: 700; }
.spotlight-card__body { padding: 24px 28px; }
.spotlight-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; }

/* --- Resources Grid --- */
.resources-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.resource-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 32px; transition: all 0.3s; }
.resource-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.resource-card__icon { width: 48px; height: 48px; background: var(--color-gray-50); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 22px; margin-bottom: 16px; }
.resource-card__title { font-size: 16px; font-weight: 700; margin-bottom: 8px; }
.resource-card__desc { font-size: 13px; color: var(--color-gray-500); line-height: 1.6; }

/* --- Membership Benefits --- */
.benefits-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.benefit-card { text-align: center; padding: 36px 24px; background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); transition: all 0.3s; }
.benefit-card:hover { box-shadow: var(--shadow-lg); }
.benefit-card__value { font-size: 36px; font-weight: 800; font-family: var(--font-heading); letter-spacing: -0.02em; margin-bottom: 8px; }
.benefit-card__value--highlight { color: var(--color-burgundy); }
.benefit-card__title { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
.benefit-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; }

/* --- Value Props --- */
.value-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.value-card { padding: 36px; background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); transition: all 0.3s; }
.value-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-4px); }
.value-card__icon { width: 52px; height: 52px; background: var(--color-gray-50); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 24px; margin-bottom: 20px; }
.value-card__title { font-size: 18px; font-weight: 700; margin-bottom: 10px; }
.value-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; }

/* --- Membership Management --- */
.mgmt-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.mgmt-card { background: var(--color-white); border: 1px solid var(--color-gray-200); border-radius: var(--radius-lg); padding: 32px; transition: all 0.3s; }
.mgmt-card:hover { box-shadow: var(--shadow-lg); }
.mgmt-card__icon { width: 48px; height: 48px; background: var(--color-gray-50); border-radius: var(--radius-md); display: flex; align-items: center; justify-content: center; font-size: 22px; margin-bottom: 16px; }
.mgmt-card__title { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
.mgmt-card__desc { font-size: 14px; color: var(--color-gray-500); line-height: 1.6; }

/* --- Footer --- */
.footer { background: var(--color-black); color: var(--color-white); padding: 72px 0 40px; }
.footer__inner { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px; }
.footer__brand { }
.footer__logo { display: flex; align-items: center; gap: 10px; font-family: var(--font-heading); font-size: 20px; font-weight: 700; margin-bottom: 16px; }
.footer__logo-icon { width: 30px; height: 30px; background: var(--color-lime); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; color: var(--color-black); font-weight: 800; font-size: 16px; }
.footer__desc { font-size: 13px; color: var(--color-gray-400); line-height: 1.6; max-width: 260px; }
.footer__col-title { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--color-gray-400); margin-bottom: 20px; }
.footer__link { display: block; padding: 6px 0; font-size: 14px; color: var(--color-gray-300); transition: color 0.2s; }
.footer__link:hover { color: var(--color-lime); }
.footer__bottom { border-top: 1px solid var(--color-gray-800); margin-top: 48px; padding-top: 28px; display: flex; justify-content: space-between; align-items: center; font-size: 13px; color: var(--color-gray-500); flex-wrap: wrap; gap: 16px; }
.footer__social { display: flex; gap: 16px; }
.footer__social-link { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--color-gray-700); display: flex; align-items: center; justify-content: center; color: var(--color-gray-400); transition: all 0.2s; font-size: 14px; }
.footer__social-link:hover { border-color: var(--color-lime); color: var(--color-lime); }

/* --- Page-specific Hero variants --- */
.hero--page { padding: 140px 0 60px; }
.hero--page .hero__inner { text-align: center; }
.hero--page .hero__title { font-size: clamp(32px, 5vw, 52px); }

/* --- Scroll Animation --- */
.animate-on-scroll { opacity: 0; transform: translateY(30px); transition: all 0.6s ease; }
.animate-on-scroll.visible { opacity: 1; transform: translateY(0); }

/* ==========================================================================
   Responsive
   ========================================================================== */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .cards-grid { grid-template-columns: repeat(2, 1fr); }
  .cards-grid--4, .ai-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .social-proof { grid-template-columns: repeat(2, 1fr); gap: 24px; }
  .global-scale { grid-template-columns: 1fr; gap: 40px; }
  .why-tabs__panel-inner { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .file-types { grid-template-columns: repeat(3, 1fr); }
  .feature-alt { grid-template-columns: 1fr; gap: 32px; }
  .feature-alt:nth-child(even) { direction: ltr; }
  .footer__inner { grid-template-columns: 1fr 1fr 1fr; }
  .hero__preview-sidebar { width: 140px; }
  .pricing-grid { grid-template-columns: 1fr; max-width: 400px; }
  .pricing-card--featured { transform: none; }
  .pricing-card--featured:hover { transform: translateY(-4px); }
  .steps { grid-template-columns: 1fr; max-width: 360px; margin: 0 auto; }
  .spotlight-grid { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; }
  .benefits-grid, .mgmt-grid, .value-grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .resources-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav__links { display: none; }
  .nav__cta { display: none; }
  .nav__toggle { display: flex; }
  .section { padding: 64px 0; }
  .hero { padding: 120px 0 48px; }
  .hero--page { padding: 110px 0 48px; }
  .product-grid, .cards-grid, .cards-grid--4, .ai-grid { grid-template-columns: 1fr; max-width: 400px; margin-left: auto; margin-right: auto; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .stats-bar__inner { gap: 40px; }
  .testimonials__grid { grid-template-columns: 1fr; }
  .why-tabs__nav { gap: 6px; }
  .why-tabs__trigger { padding: 10px 16px; font-size: 13px; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types { grid-template-columns: repeat(2, 1fr); }
  .footer__inner { grid-template-columns: 1fr 1fr; }
  .hero__preview-body { flex-direction: column; min-height: auto; }
  .hero__preview-sidebar { width: 100%; flex-direction: row; overflow-x: auto; padding: 12px; border-right: none; border-bottom: 1px solid var(--color-gray-200); }
  .hero__preview-nav-item { white-space: nowrap; }
  .hero__preview-stat-row { grid-template-columns: 1fr; }
  .cta-banner { padding: 40px 24px; }
  .cta-banner__title { font-size: 28px; }
  .global-scale__content h2 { font-size: 28px; }
  .social-proof { grid-template-columns: 1fr 1fr; }
  .pricing-grid { grid-template-columns: 1fr; max-width: 380px; }
  .pricing-card--featured { transform: none; }
  .pricing-card--featured:hover { transform: translateY(-4px); }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .footer__inner { grid-template-columns: 1fr; }
  .hero__actions { flex-direction: column; width: 100%; }
  .hero__actions .btn { width: 100%; }
  .cta-banner__actions { flex-direction: column; }
  .cta-banner__actions .btn { width: 100%; }
  .stats-bar__inner { flex-direction: column; gap: 24px; }
  .why-tabs__trigger { width: 100%; text-align: center; }
  .tools-grid { grid-template-columns: repeat(2, 1fr); }
  .file-types { grid-template-columns: 1fr 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .hero__tabs { flex-direction: column; width: 100%; }
  .hero__tab { width: 100%; }
  .testimonials__controls { gap: 8px; }
  .testimonials__btn { width: 36px; height: 36px; font-size: 14px; }
}

